This is a complete HTML document that creates a simple joke generator. When you click the button, it displays one of four random jokes.
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Random joke generator</title>
    <style>
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
            background: linear-gradient(145deg, #f8faff 0%, #e9eef5 100%);
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 1.5rem;
            margin: 0;
        }

        .card {
            background: rgba(255, 255, 255, 0.85);
            backdrop-filter: blur(8px);
            border-radius: 2.5rem;
            padding: 2.5rem 2rem;
            width: 100%;
            max-width: 660px;
            box-shadow: 
                0 20px 40px -12px rgba(0, 0, 0, 0.25),
                0 8px 24px -8px rgba(0, 20, 40, 0.15),
                inset 0 1px 2px rgba(255, 255, 255, 0.8);
            border: 1px solid rgba(255, 255, 255, 0.6);
            transition: box-shadow 0.2s ease;
            text-align: center;
        }

        h1 {
            font-size: 2rem;
            font-weight: 600;
            letter-spacing: -0.02em;
            color: #1e2b3f;
            margin-bottom: 1.75rem;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.4rem;
        }

        h1 span {
            font-size: 2.2rem;
            line-height: 1;
        }

        .joke-box {
            background: #ffffffcc;
            backdrop-filter: blur(4px);
            border-radius: 2rem;
            padding: 2rem 1.75rem;
            min-height: 140px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 1px solid #ffffff;
            box-shadow: 
                inset 0 2px 6px rgba(0, 0, 0, 0.02),
                0 6px 12px -6px rgba(0, 0, 0, 0.1);
            margin-bottom: 2rem;
            transition: background 0.2s;
        }

        #jokeDisplay {
            font-size: 1.5rem;
            line-height: 1.5;
            font-weight: 500;
            color: #0f1a2e;
            word-break: break-word;
            font-style: normal;
            transition: opacity 0.2s;
        }

        .fallback-message {
            font-size: 1.2rem;
            color: #5e6f8d;
            font-weight: 400;
            font-style: italic;
        }

        button {
            background: #1e2b3f;
            border: none;
            color: white;
            font-size: 1.3rem;
            font-weight: 500;
            padding: 1rem 2.8rem;
            border-radius: 3rem;
            cursor: pointer;
            box-shadow: 
                0 12px 20px -12px rgba(20, 40, 70, 0.4),
                0 4px 8px -4px rgba(0, 0, 0, 0.1),
                inset 0 1px 2px rgba(255, 255, 255, 0.3);
            transition: transform 0.15s ease, background 0.2s, box-shadow 0.2s;
            letter-spacing: 0.02em;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 0.6rem;
            border: 1px solid #2e405b;
        }

        button:hover {
            background: #26374f;
            box-shadow: 
                0 18px 24px -14px rgba(20, 40, 70, 0.5),
                0 6px 12px -6px rgba(0, 0, 0, 0.2),
                inset 0 1px 2px rgba(255, 255, 255, 0.4);
        }

        button:active {
            transform: scale(0.97);
            background: #141f2e;
            box-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.3);
        }

        /* subtle responsive tweaks */
        @media (max-width: 480px) {
            .card {
                padding: 1.75rem 1.25rem;
                border-radius: 2rem;
            }

            h1 {
                font-size: 1.6rem;
                margin-bottom: 1.25rem;
            }

            .joke-box {
                padding: 1.5rem 1rem;
                min-height: 120px;
            }

            #jokeDisplay {
                font-size: 1.25rem;
            }

            button {
                font-size: 1.15rem;
                padding: 0.9rem 1.8rem;
            }
        }
    </style>
</head>
<body>
    <div class="card">
        <h1>
            <span>🤣</span> Random Joke
        </h1>

        <div class="joke-box">
            <div id="jokeDisplay" class="fallback-message">
                Click the button for a random joke!
            </div>
        </div>

        <button id="jokeBtn">
            🎲 Tell me a joke
        </button>
    </div>

    <script>
        (function() {
            // ---------- Four jokes (clean, fun, variety) ----------
            const jokes = [
                "Why don't scientists trust atoms? Because they make up everything!",
                "I told my computer I needed a break, and it said: 'No problem – I'll go to sleep.'",
                "Parallel lines have so much in common… it’s a shame they’ll never meet.",
                "What do you call a fake noodle? An impasta!"
            ];

            // ---------- DOM references ----------
            const jokeDisplay = document.getElementById('jokeDisplay');
            const jokeBtn = document.getElementById('jokeBtn');

            // ---------- Helper to get a random integer (0 to max-1) ----------
            function getRandomInt(max) {
                return Math.floor(Math.random() * max);
            }

            // ---------- Display a random joke ----------
            function showRandomJoke() {
                const randomIndex = getRandomInt(jokes.length);
                const randomJoke = jokes[randomIndex];

                // Update the text, remove fallback style (if present)
                jokeDisplay.textContent = randomJoke;
                jokeDisplay.classList.remove('fallback-message');
            }

            // ---------- Attach click listener ----------
            jokeBtn.addEventListener('click', showRandomJoke);

            // Optional: if the user clicks the button, it always shows a joke.
            // No initial auto-joke; keeps the "click to reveal" experience.
        })();
    </script>
</body>
</html>
```
### How the Joke Generator Works

Clicking the button instantly picks one of four jokes and displays it in the card. The process is straightforward and responsive.

- **Random selection**: Each click uses a random index to choose a joke from a predefined list.
- **Interactive feedback**: The joke appears in a styled box, and the button has a subtle press animation.
- **Clean interface**: A centered card with a soft gradient background keeps the focus on the joke and the button.

---

**Optimization Tip:** You can replace the four jokes inside the `jokes` array (around line 138) with your own text. Each joke should be a string in quotes, separated by commas.

