```python
import math
import random

ROWS, COLS = 6, 7
EMPTY = '.'
PLAYER = 'X'   # Human
AI = 'O'       # Computer

def create_board():
    return [[EMPTY] * COLS for _ in range(ROWS)]

def print_board(board):
    print()
    for row in board:
        print(' '.join(row))
    print(' '.join(str(i) for i in range(COLS)))
    print()

def is_valid_col(board, col):
    return board[0][col] == EMPTY

def get_open_row(board, col):
    for r in range(ROWS - 1, -1, -1):
        if board[r][col] == EMPTY:
            return r
    return None

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def winning_move(board, piece):
    # Horizontal
    for r in range(ROWS):
        for c in range(COLS - 3):
            if all(board[r][c+i] == piece for i in range(4)):
                return True
    # Vertical
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r+i][c] == piece for i in range(4)):
                return True
    # Diagonal (down-right)
    for r in range(ROWS - 3):
        for c in range(COLS - 3):
            if all(board[r+i][c+i] == piece for i in range(4)):
                return True
    # Diagonal (up-right)
    for r in range(3, ROWS):
        for c in range(COLS - 3):
            if all(board[r-i][c+i] == piece for i in range(4)):
                return True
    return False

def get_valid_locations(board):
    return [c for c in range(COLS) if is_valid_col(board, c)]

def is_terminal_node(board):
    return winning_move(board, PLAYER) or winning_move(board, AI) or len(get_valid_locations(board)) == 0

def evaluate_window(window, piece):
    opp_piece = PLAYER if piece == AI else AI
    score = 0
    if window.count(piece) == 4:
        score += 100
    elif window.count(piece) == 3 and window.count(EMPTY) == 1:
        score += 5
    elif window.count(piece) == 2 and window.count(EMPTY) == 2:
        score += 2
    if window.count(opp_piece) == 3 and window.count(EMPTY) == 1:
        score -= 4
    return score

def score_position(board, piece):
    score = 0

    # Score center column
    center_array = [board[r][COLS // 2] for r in range(ROWS)]
    score += center_array.count(piece) * 3

    # Horizontal
    for r in range(ROWS):
        row_array = board[r]
        for c in range(COLS - 3):
            window = row_array[c:c + 4]
            score += evaluate_window(window, piece)

    # Vertical
    for c in range(COLS):
        col_array = [board[r][c] for r in range(ROWS)]
        for r in range(ROWS - 3):
            window = col_array[r:r + 4]
            score += evaluate_window(window, piece)

    # Diagonal down-right
    for r in range(ROWS - 3):
        for c in range(COLS - 3):
            window = [board[r+i][c+i] for i in range(4)]
            score += evaluate_window(window, piece)

    # Diagonal up-right
    for r in range(3, ROWS):
        for c in range(COLS - 3):
            window = [board[r-i][c+i] for i in range(4)]
            score += evaluate_window(window, piece)

    return score

def minimax(board, depth, alpha, beta, maximizing_player):
    valid_locations = get_valid_locations(board)
    terminal = is_terminal_node(board)

    if depth == 0 or terminal:
        if terminal:
            if winning_move(board, AI):
                return (None, 1000000000)
            elif winning_move(board, PLAYER):
                return (None, -1000000000)
            else:  # No more valid moves
                return (None, 0)
        else:
            return (None, score_position(board, AI))

    if maximizing_player:
        value = -math.inf
        best_col = random.choice(valid_locations)
        for col in valid_locations:
            row = get_open_row(board, col)
            temp_board = [r[:] for r in board]
            drop_piece(temp_board, row, col, AI)
            new_score = minimax(temp_board, depth - 1, alpha, beta, False)[1]
            if new_score > value:
                value = new_score
                best_col = col
            alpha = max(alpha, value)
            if alpha >= beta:
                break
        return best_col, value
    else:
        value = math.inf
        best_col = random.choice(valid_locations)
        for col in valid_locations:
            row = get_open_row(board, col)
            temp_board = [r[:] for r in board]
            drop_piece(temp_board, row, col, PLAYER)
            new_score = minimax(temp_board, depth - 1, alpha, beta, True)[1]
            if new_score < value:
                value = new_score
                best_col = col
            beta = min(beta, value)
            if alpha >= beta:
                break
        return best_col, value

def main():
    board = create_board()
    game_over = False
    turn = random.choice([PLAYER, AI])

    print_board(board)
    print(f"{'You' if turn == PLAYER else 'AI'} go first!")

    while not game_over:
        if turn == PLAYER:
            valid = False
            while not valid:
                try:
                    col = int(input(f"Your turn ({PLAYER}). Pick a column (0-{COLS-1}): "))
                    if col in get_valid_locations(board):
                        valid = True
                    else:
                        print("Invalid or full column, try again.")
                except ValueError:
                    print("Enter a valid number.")

            row = get_open_row(board, col)
            drop_piece(board, row, col, PLAYER)

            if winning_move(board, PLAYER):
                print_board(board)
                print("🎉 You win!")
                game_over = True

        else:
            print("AI is thinking...")
            col, _ = minimax(board, 5, -math.inf, math.inf, True)
            if col is not None and is_valid_col(board, col):
                row = get_open_row(board, col)
                drop_piece(board, row, col, AI)

                if winning_move(board, AI):
                    print_board(board)
                    print("🤖 AI wins!")
                    game_over = True

        print_board(board)

        if len(get_valid_locations(board)) == 0 and not game_over:
            print("It's a draw!")
            game_over = True

        turn = PLAYER if turn == AI else AI

if __name__ == "__main__":
    main()
```

### How it works
- **Board**: 6 rows × 7 columns, represented as a 2D list.
- **Human player**: enters a column number (0–6) to drop a piece (`X`).
- **AI player**: uses **minimax with alpha-beta pruning** (depth 5) to choose the best move (`O`).
- **Evaluation function**: scores board positions based on potential 4-in-a-row windows, favoring center control and blocking opponent threats.
- **Win detection**: checks horizontal, vertical, and both diagonal directions.

### To play
Just run the script:
```bash
python connect4.py
```
Then enter column numbers when prompted. The AI will respond after each of your moves.

You can increase the `depth` parameter in `minimax(board, 5, ...)` for a stronger (but slower) AI, or decrease it for faster but weaker play.

